export type CloneProjectRows = {
  orgId: OrgId;
  sourceProjectId: ProjectId;
  name: string;
  slug: string;
  key: string;
  authorId: UserId;
  includeIssues: boolean;
};

/**
 * Writes a clone in one transaction: the new project row (settings copied
 * from the source, starting `active`) and, when asked, every live issue of
 * the source as fresh work. Copies are numbered from 1 in the source's number
 * order, start in `backlog`, unassigned and unstamped, authored by
 * `authorId`, and keep their labels. Comments, attachments and parent links
 * are not copied.
 *
 * Quota and permission gates are the caller's job — this only writes.
 */
export async function cloneProjectWithIssues(
  input: CloneProjectRows,
): Promise<{ project: Project; issuesCopied: number }> {
  const db = getDb();
  const source = db
    .select()
    .from(projects)
    .where(
      and(
        orgPredicate(projects.orgId, input.orgId),
        eq(projects.id, input.sourceProjectId),
      ),
    )
    .get();
  if (!source) throw new Error(`Project ${input.sourceProjectId} not found`);

  const slug = uniqueSlug(input.slug, await listTakenProjectSlugs(input.orgId));
  const stamp = toIsoTimestamp(new Date());

  return db.transaction((tx) => {
    const row = tx
      .insert(projects)
      .values({
        id: newId(),
        orgId: input.orgId,
        name: input.name,
        slug,
        key: input.key,
        description: source.description,
        visibility: source.visibility,
        status: "active",
        leadId: source.leadId,
        color: source.color,
        startsAt: null,
        targetDate: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();

    if (!input.includeIssues) {
      return { project: toProject(row), issuesCopied: 0 };
    }

    const sourceIssues = tx
      .select()
      .from(issues)
      .where(
        and(
          ...compact(
            orgPredicate(issues.orgId, input.orgId),
            eq(issues.projectId, input.sourceProjectId),
            livePredicate(issues.archivedAt, {}),
          ),
        ),
      )
      .orderBy(asc(issues.number))
      .all();

    const labelRows =
      sourceIssues.length === 0
        ? []
        : tx
            .select()
            .from(issueLabels)
