/**
 * Clones a live project into a new one in the same workspace. Gated like a
 * creation: read on the source, create on the workspace, the project quota,
 * and — when issues come along — the per-project issue quota for the whole
 * batch, checked before anything is written. Live issues only; progress is
 * reset (see `projectRepo.cloneProjectWithIssues`). Publishes one
 * `project.cloned`; the search, usage and audit listeners do the rest.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:read", projectResource(source));
  assertCan(actor, "project:create", orgResource(input.orgId));
  assertNotArchived("Project", source.id, source);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

