import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { subscribe } from "@/lib/event-bus";
import { getDb } from "@/server/db";
import { registerEventHandlers } from "@/server/services/event-registry";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());

describe("tmp clone check", () => {
  it("clones", async () => {
    const t = await createTenant("clonecheck", "growth");
    const src = t.project;
    const a = await issueService.createIssue(t.actors.member, issueInput(t.org.id, src.id, { title: "A", priority: "high" }));
    const b = await issueService.createIssue(t.actors.member, issueInput(t.org.id, src.id, { title: "B" }));
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: b.id, status: "done" });
    await issueService.archiveIssue(t.actors.member, t.org.id, a.id);
    const c = await issueService.createIssue(t.actors.member, issueInput(t.org.id, src.id, { title: "C" }));
    const before = await usageRepo.getUsage(t.org.id);
    let got: string[] = [];
    const off = subscribe("project.cloned", (p) => { got.push(p.issuesCopied + ""); });
    const clone = await projectService.cloneProject(t.actors.member, { orgId: t.org.id, projectId: src.id, name: "Clone Two", slug: "platform", key: "CLO", includeIssues: true });
    off();
    expect(clone.slug).toBe("platform-2");
    expect(clone.key).toBe("CLO");
    expect(got).toEqual(["2"]);
    const copies = await issueRepo.listAllLiveIssues(t.org.id, clone.id);
    expect(copies.map((i) => [i.title, i.number, i.status, i.assigneeId, i.authorId === t.userIds.member])).toEqual([["B", 1, "backlog", null, true], ["C", 2, "backlog", null, true]]);
    expect(copies.every((i) => i.completedAt === null)).toBe(true);
    expect((await issueRepo.listAllLiveIssues(t.org.id, src.id)).length).toBe(2);
    const after = await usageRepo.getUsage(t.org.id);
    expect(after.projectsUsed).toBe(before.projectsUsed + 1);
    expect(after.issuesUsed).toBe(before.issuesUsed + 2);
    const hits = await searchRepo.searchDocuments({ orgId: t.org.id, q: "Clone", limit: 10, cursor: null } as never);
    expect(hits.items.length).toBeGreaterThan(0);
    const audit = await activityRepo.listActivity({ orgId: t.org.id, action: ["project.cloned"], limit: 10, cursor: null } as never);
    expect(audit.items[0]?.subjectId).toBe(clone.id);
    expect(audit.items[0]?.metadata).toEqual({ sourceProjectId: src.id, issuesCopied: 2 });
    const cloneNoIssues = await projectService.cloneProject(t.actors.member, { orgId: t.org.id, projectId: src.id, name: "Clone Three", slug: "clone-three", key: "CLT", includeIssues: false });
    expect(await issueRepo.countIssues(t.org.id, cloneNoIssues.id)).toBe(0);
  });
});
EOF
